// Audio: sound effects are WAV assets (generated by tools/assets/gen-audio.mjs)
// played through Phaser; the ambient score is synthesized live (drone + bells +
// war drums during waves) so it can react to game state.
import * as Phaser from 'phaser';
import { G } from '../core/state';
import { hooks } from '../core/events';
import { pick } from '../core/util';

let scene: Phaser.Scene | null = null;
const last: Record<string, number> = {};
const GAP: Record<string, number> = { die: 50, hit: 60, slash: 60, hitstone: 80, shoot: 60, bow: 50, necro: 60, zap: 70, fireball: 80, boom: 70, frost: 70, arcane: 60 };

export function initAudio(s: Phaser.Scene) {
  scene = s;
  hooks.sfx = (name: string, vol = 1) => {
    if (!scene || !G.settings || G.settings.sfx <= 0) return;
    const now = performance.now();
    if (now - (last[name] || 0) < (GAP[name] || 30)) return;
    last[name] = now;
    if (!scene.cache.audio.exists('sfx_' + name)) return;
    try { scene.sound.play('sfx_' + name, { volume: G.settings.sfx * 0.7 * vol }); } catch { /* audio locked until first gesture */ }
  };
}

// ---------------- ambient score ----------------
let ac: AudioContext | null = null, bus: GainNode | null = null, beat = 0, started = false;
const SCALE = [146.83, 155.56, 174.61, 196.0, 220.0, 233.08, 261.63, 293.66];
export function startMusic() {
  if (started) { if (ac && ac.state === 'suspended') ac.resume(); return; }
  try {
    ac = new (window.AudioContext || (window as any).webkitAudioContext)();
    bus = ac.createGain(); bus.connect(ac.destination);
    applyMusicVolume();
    const lp = ac.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 420; lp.connect(bus);
    const lfo = ac.createOscillator(), lfoG = ac.createGain(); lfo.frequency.value = 0.06; lfoG.gain.value = 180; lfo.connect(lfoG); lfoG.connect(lp.frequency); lfo.start();
    for (const [f, t, v] of [[73.42, 'sawtooth', 0.05], [73.9, 'sawtooth', 0.05], [110, 'triangle', 0.04], [36.7, 'sine', 0.12]] as [number, OscillatorType, number][]) {
      const o = ac.createOscillator(), g = ac.createGain(); o.type = t; o.frequency.value = f; g.gain.value = v; o.connect(g); g.connect(lp); o.start();
    }
    setInterval(tick, 300);
    started = true;
  } catch { /* no audio */ }
}
export function applyMusicVolume() { if (bus) bus.gain.value = (G.settings ? G.settings.music : 0.4) * 0.5; }
function bell(freq: number, vol: number) {
  const t = ac!.currentTime;
  [1, 2.01, 3.03].forEach((m, i) => {
    const o = ac!.createOscillator(), g = ac!.createGain(); o.frequency.value = freq * m;
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol / (i + 1), t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + 3 / (i + 1));
    o.connect(g); g.connect(bus!); o.start(t); o.stop(t + 3.2);
  });
}
function drum(vol: number) {
  const t = ac!.currentTime, o = ac!.createOscillator(), g = ac!.createGain();
  o.frequency.setValueAtTime(90, t); o.frequency.exponentialRampToValueAtTime(40, t + 0.3);
  g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.35); o.connect(g); g.connect(bus!); o.start(t); o.stop(t + 0.4);
}
function tick() {
  if (!ac || !G.settings || G.settings.music <= 0 || document.hidden) return;
  beat++;
  if (beat % 8 === 0 && Math.random() < 0.55) bell(pick(SCALE) * (Math.random() < 0.3 ? 2 : 1), 0.05);
  if (G.phase === 'wave' && !G.paused && !G.modal) {
    if (beat % 4 === 0) drum(0.35);
    if (beat % 4 === 2 && Math.random() < 0.5) drum(0.18);
    if (G.bossBar && beat % 2 === 1) drum(0.2);
  }
}
